<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>LifeOS desktop panel</title><link rel="stylesheet" href="/assets/desktop-panel.css"></head>
<body><main data-csrf="<?= e($_SESSION['csrf'] ?? '') ?>" class="panel-shell">
<header class="panel-header" data-drag-handle title="Drag to move panel"><div class="panel-brand"><img src="/assets/brand/favicon-32.png" width="24" height="24" alt=""><span>LifeOS<small>Your personal space</small></span></div><nav aria-label="Panel controls"><button class="icon-button" data-preferences-toggle aria-label="Customize panel" aria-expanded="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 17h16M8 4v6m8 4v6"/></svg></button><button class="icon-button close-button" data-close aria-label="Close panel"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg></button></nav></header>
<div class="panel-heading"><div><p data-date>Loading your day…</p><h1>Right now</h1></div><button class="add-button" data-add-toggle><span aria-hidden="true">+</span> Add</button></div>
<div class="panel-content">
<section class="card preferences" data-preferences hidden><div class="section-title"><h2>Your panel</h2><span class="caption">Make it yours</span></div><div class="preference-grid"><?php foreach(['showTasks'=>'Tasks','showTodos'=>'To-do list','showAssignments'=>'Assignments','showExams'=>'Exams','showLectures'=>'Lectures & events','showNotes'=>'Notes'] as $key=>$label): ?><label><input type="checkbox" data-panel-pref="<?= e($key) ?>"><span><?= e($label) ?></span></label><?php endforeach; ?></div><label class="auto-hide"><input type="checkbox" name="autoHide"><span>Hide when I switch to another app</span></label><div class="preference-grid"><label>Text size<select data-display-pref name="textSize"><option value="12">Small</option><option value="14">Comfortable</option><option value="16">Large</option><option value="18">Extra large</option></select></label><label>Appearance<select data-display-pref name="theme"><option value="system">Windows setting</option><option value="light">Light</option><option value="dark">Dark</option></select></label><label>Width (pixels)<input data-panel-width type="number" min="320" max="3840" step="10"></label><label>Height (pixels)<input data-panel-height type="number" min="360" max="2160" step="10"></label></div><div class="form-actions"><button type="button" data-apply-size>Apply size</button><button type="button" data-reset-layout>Reset position &amp; size</button></div><p class="caption">Drag the header to move. Drag the bottom corner to resize. Your layout is saved.</p><p data-preference-status role="status"></p></section>
<form class="card add-form" data-add-form hidden><div class="section-title"><h2>Quick add</h2><span class="caption">Saved in LifeOS</span></div><label>Type<select name="kind"><option value="task">Task</option><option value="todo">To-do</option><option value="note">Note</option></select></label><label>Title<input name="title" maxlength="160" required placeholder="What would you like to remember?"></label><label data-due-field>Date<input name="due" type="date"></label><label data-note-body hidden>Note<textarea name="body" maxlength="3000" rows="4" placeholder="Write a quick note"></textarea></label><div class="form-actions"><button type="button" data-cancel-add>Cancel</button><button type="submit" class="primary">Save</button></div><p data-form-status role="status"></p></form>
<section class="card schedule-card"><div class="section-title"><h2>Today’s schedule</h2><span class="count-pill" data-schedule-count>0</span></div><div class="table-heading" aria-hidden="true"><span>Time</span><span>What’s next</span><span>Type</span></div><div data-items><p class="empty">Checking your calendar and tasks…</p></div></section>
<section class="card list-card" data-todo-section><div class="section-title"><h2>To-do</h2><button class="section-add" data-section-add="todo" aria-label="Add a to-do">+</button></div><div data-todos></div></section>
<section class="card list-card" data-notes-section><div class="section-title"><h2>Notes</h2><button class="section-add" data-section-add="note" aria-label="Add a note">+</button></div><div data-notes></div></section>
</div><footer><a href="/planner" data-open-planner>Open planner <span aria-hidden="true">↗</span></a><kbd title="Show or hide this panel">Win + \</kbd><button class="refresh-button" data-refresh><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 7v5h-5M4 17v-5h5m10-2a7 7 0 0 0-12-4M5 14a7 7 0 0 0 12 4"/></svg><span>Refresh</span></button></footer>
<button type="button" class="resize-grip" data-resize aria-label="Resize panel" title="Drag to resize">◢</button></main><script src="/assets/desktop-panel.js" defer></script></body></html>
